import React from 'react';
import Avatar from '../ui/Avatar';
import Button from '../ui/Button';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { zodResolver } from '@hookform/resolvers/zod';
import { useCreateTweetMutation } from '../../api/tweetApi';
import toast from 'react-hot-toast';

const tweetSchema = z.object({
  content: z.string().min(1, "Tweet cannot be empty").max(280, "Tweet max length is 280 characters"),
});

const TweetComposer = ({ user }) => {
  const [createTweet, { isLoading }] = useCreateTweetMutation();
  const { register, handleSubmit, watch, reset, formState: { errors } } = useForm({
    resolver: zodResolver(tweetSchema),
    defaultValues: { content: '' }
  });

  const content = watch('content');
  const remaining = 280 - (content?.length || 0);

  const onSubmit = async (data) => {
    try {
      await createTweet(data.content).unwrap();
      toast.success('Tweet posted successfully');
      reset();
    } catch (err) {
      // Error handled by interceptor
    }
  };

  return (
    <div className="flex gap-4 bg-bg-primary p-4 border border-border-default rounded-[12px] shadow-sm mb-6">
      <Avatar src={user?.avatar} name={user?.username} size="md" className="shrink-0" />
      <form onSubmit={handleSubmit(onSubmit)} className="flex-1 flex flex-col min-w-0">
        <textarea
          {...register('content')}
          placeholder="What's happening?"
          className="w-full bg-transparent resize-none overflow-hidden outline-none font-body text-[15px] text-text-primary placeholder:text-text-muted transition-colors border-b border-transparent focus:border-red pb-2 min-h-[50px] max-h-[200px]"
          onInput={(e) => {
            e.target.style.height = 'auto';
            e.target.style.height = `${e.target.scrollHeight}px`;
          }}
        />
        {errors.content && <span className="text-red font-body text-[12px] mt-1">{errors.content.message}</span>}

        <div className="flex justify-between items-end mt-3 border-t border-border-secondary pt-3">
          <span className={`font-mono text-[11px] ${remaining < 20 ? 'text-gold' : remaining < 0 ? 'text-red' : 'text-text-disabled'}`}>
            {remaining}
          </span>
          <Button type="submit" size="sm" isLoading={isLoading} disabled={remaining < 0 || content.trim() === ''} className="bg-blue hover:bg-blue/90 h-[32px] rounded-full px-5 pointer-events-auto">
            Post
          </Button>
        </div>
      </form>
    </div>
  );
};

export default TweetComposer;

import { useSelector, useDispatch } from 'react-redux';
import { useLoginMutation, useLogoutMutation } from '../api/userApi';
import { setUser, setAccessToken, logout as clearAuth } from '../app/authSlice';

export const useAuth = () => {
  const { user, isAuthenticated, loading } = useSelector((state) => state.auth);
  const dispatch = useDispatch();
  const [loginMutation] = useLoginMutation();
  const [logoutMutation] = useLogoutMutation();

  const login = async (credentials) => {
    try {
      const response = await loginMutation(credentials).unwrap();
      dispatch(setUser(response.data.user));
      dispatch(setAccessToken(response.data.accessToken));
      return response;
    } catch (error) {
      throw error;
    }
  };

  const logout = async () => {
    try {
      await logoutMutation().unwrap();
    } catch (error) {
      console.error('Logout error', error);
    } finally {
      dispatch(clearAuth());
    }
  };

  return {
    user,
    isAuthenticated,
    loading,
    login,
    logout,
  };
};

import { useState } from 'react';
import { useToggleVideoLikeMutation, useToggleCommentLikeMutation, useToggleTweetLikeMutation } from '../api/likeApi';
import toast from 'react-hot-toast';

export const useLikeToggle = (type, id, initialCount = 0, initialLiked = false) => {
  const [isLiked, setIsLiked] = useState(initialLiked);
  const [likeCount, setLikeCount] = useState(initialCount);

  const [toggleVideoLike] = useToggleVideoLikeMutation();
  const [toggleCommentLike] = useToggleCommentLikeMutation();
  const [toggleTweetLike] = useToggleTweetLikeMutation();

  const toggleLike = async () => {
    // Optimistic update
    const previousIsLiked = isLiked;
    const previousLikeCount = likeCount;

    setIsLiked(!isLiked);
    setLikeCount((prev) => (isLiked ? prev - 1 : prev + 1));

    try {
      if (type === 'video') await toggleVideoLike(id).unwrap();
      else if (type === 'comment') await toggleCommentLike(id).unwrap();
      else if (type === 'tweet') await toggleTweetLike(id).unwrap();
    } catch (error) {
      // Revert on error
      setIsLiked(previousIsLiked);
      setLikeCount(previousLikeCount);
      toast.error('Failed to toggle like');
    }
  };

  return { isLiked, likeCount, toggleLike };
};

import React, { useState } from 'react';
import { useParams } from 'react-router-dom';
import ChannelHeader from '../components/channel/ChannelHeader';
import EditProfileModal from '../components/channel/EditProfileModal';
import VideoGrid from '../components/video/VideoGrid';
import TweetFeed from '../components/tweet/TweetFeed';
import PlaylistGrid from '../components/playlist/PlaylistGrid';
import { useGetChannelProfileQuery, useUpdateAccountMutation } from '../api/userApi';
import { useGetAllVideosQuery } from '../api/videoApi';
import { useGetUserTweetsQuery } from '../api/tweetApi';
import { useGetUserPlaylistsQuery } from '../api/playlistApi';
import { useSelector } from 'react-redux';
import Skeleton from '../components/ui/Skeleton';
import toast from 'react-hot-toast';

const Channel = () => {
  const { username } = useParams();
  const { user } = useSelector((state) => state.auth);

  const { data: profileData, isLoading: profileLoading } = useGetChannelProfileQuery(username, {
    skip: !username,
  });
  const profile = profileData?.data;
  const isOwner = user?.username === username;

  const [activeTab, setActiveTab] = useState('Videos');
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);

  const [updateAccount] = useUpdateAccountMutation();

  const handleUpdateProfile = async (data) => {
    try {
      await updateAccount(data).unwrap();
      toast.success('Profile updated');
    } catch {
      // Error handled
    }
  };

  const tabs = ['Videos', 'Tweets', 'Playlists', 'About'];

  return (
    <div className="flex flex-col w-full min-h-screen relative">
      <div className="w-full h-[120px] sm:h-[160px] md:h-[200px] overflow-hidden bg-bg-secondary border-b border-border-default -mx-4 sm:-mx-6 -mt-4 sm:-mt-6 px-4 sm:px-6 w-[calc(100%+2rem)] sm:w-[calc(100%+3rem)] relative group">
        {profileLoading ? (
          <Skeleton className="w-full h-full rounded-none" />
        ) : (
          profile?.coverImage ? (
            <img src={profile.coverImage} alt="Cover" className="w-full h-full object-cover" />
          ) : (
             <div className="w-full h-full bg-gradient-to-tr from-bg-tertiary to-border-default opacity-50" />
          )
        )}
      </div>

      <div className="px-2 mt-4">
        <ChannelHeader 
          profile={profile} 
          isLoading={profileLoading} 
          isOwner={isOwner} 
          onEditClick={() => setIsEditModalOpen(true)} 
        />

        <div className="border-b border-border-subtle mt-4">
          <div className="flex gap-6 overflow-x-auto cs-scroll">
            {tabs.map(tab => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`pb-3 font-display font-semibold text-[15px] sm:text-[16px] transition-colors relative outline-none focus-visible:text-red ${
                  activeTab === tab 
                    ? 'text-text-primary' 
                    : 'text-text-muted hover:text-text-primary'
                }`}
              >
                {tab}
                {activeTab === tab && (
                  <span className="absolute bottom-0 left-0 w-full h-[3px] bg-red rounded-t-sm" />
                )}
              </button>
            ))}
          </div>
        </div>

        <div className="pt-6">
          {activeTab === 'Videos' && <ChannelVideos userId={profile?._id} />}
          {activeTab === 'Tweets' && <ChannelTweets userId={profile?._id} />}
          {activeTab === 'Playlists' && <ChannelPlaylists userId={profile?._id} />}
          {activeTab === 'About' && <ChannelAbout profile={profile} />}
        </div>
      </div>

      {isEditModalOpen && (
        <EditProfileModal 
          isOpen={isEditModalOpen} 
          onClose={() => setIsEditModalOpen(false)} 
          user={profile} 
          onSave={handleUpdateProfile} 
        />
      )}
    </div>
  );
};

// Sub-components to keep clean
const ChannelVideos = ({ userId }) => {
  const { data, isFetching } = useGetAllVideosQuery({ userId, page: 1, limit: 20 }, { skip: !userId });
  if (!userId) return null;
  return <VideoGrid videos={data?.data?.docs} isLoading={isFetching} />;
};

const ChannelTweets = ({ userId }) => {
  const { data, isFetching } = useGetUserTweetsQuery(userId, { skip: !userId });
  if (!userId) return null;
  return <div className="max-w-[600px]"><TweetFeed tweets={data?.data} isFetching={isFetching} /></div>;
};

const ChannelPlaylists = ({ userId }) => {
  const { data, isFetching } = useGetUserPlaylistsQuery(userId, { skip: !userId });
  if (!userId) return null;
  if (isFetching) return <div className="p-4"><Skeleton className="w-[200px] h-[150px] rounded-xl" /></div>;
  return <PlaylistGrid playlists={data?.data || []} />;
};

